import json

# 記憶體中的備忘事項資料
notes = []
next_id = 1


def _find_index(note_id):
    for i, note in enumerate(notes):
        if note['id'] == note_id:
            return i
    return -1


def handle(method: str, path: str, body: bytes):
    global notes, next_id

    if path != '/' and path.endswith('/'):
        path = path.rstrip('/')

    if path == '/notes':
        if method == 'GET':
            return 200, {'items': list(notes)}
        if method == 'POST':
            try:
                data = json.loads(body.decode('utf-8')) if body else {}
            except (ValueError, UnicodeDecodeError):
                return 400, {'error': '請求內容必須是有效的 JSON'}
            if not isinstance(data, dict):
                return 400, {'error': '請求內容必須是 JSON 物件'}
            text = data.get('text')
            if not isinstance(text, str) or not text.strip():
                return 400, {'error': '請輸入備忘事項內容'}
            note = {'id': str(next_id), 'text': text.strip()}
            next_id += 1
            notes.append(note)
            return 201, dict(note)
        return 405, {'error': '不支援此請求方法'}

    if path.startswith('/notes/'):
        note_id = path[len('/notes/'):]
        if not note_id or '/' in note_id:
            return 404, {'error': '找不到此路徑'}
        if method == 'DELETE':
            idx = _find_index(note_id)
            if idx < 0:
                return 404, {'error': '找不到指定的備忘事項'}
            del notes[idx]
            return 200, {'deleted': True, 'id': note_id}
        return 405, {'error': '不支援此請求方法'}

    return 404, {'error': '找不到此路徑'}

