document.addEventListener('DOMContentLoaded', () => {
    const noteForm = document.getElementById('noteForm');
    const noteInput = document.getElementById('noteInput');
    const notesList = document.getElementById('notesList');
    const errorBox = document.getElementById('errorBox');

    function showError(message) {
        errorBox.textContent = message;
        errorBox.hidden = false;
    }

    function clearError() {
        errorBox.textContent = '';
        errorBox.hidden = true;
    }

    // 呼叫 API，非 2xx 時丟出含有伺服器錯誤訊息的例外
    async function callApi(path, options) {
        const response = await fetch(path, options);
        let data = null;
        try {
            data = await response.json();
        } catch (e) {
            data = null;
        }
        if (!response.ok) {
            const message = data && data.error ? data.error : '伺服器回應錯誤（' + response.status + '）';
            throw new Error(message);
        }
        return data;
    }

    // 獲取所有備忘事項
    async function fetchNotes() {
        try {
            const data = await callApi('api/notes');
            renderNotes((data && data.items) || []);
        } catch (error) {
            showError('獲取備忘事項失敗：' + error.message);
        }
    }

    // 渲染備忘事項列表
    function renderNotes(notes) {
        notesList.innerHTML = '';
        notes.forEach(note => {
            const li = document.createElement('li');
            const span = document.createElement('span');
            span.textContent = note.text;
            li.appendChild(span);

            const deleteBtn = document.createElement('button');
            deleteBtn.type = 'button';
            deleteBtn.textContent = '刪除';
            deleteBtn.addEventListener('click', () => deleteNote(note.id));

            li.appendChild(deleteBtn);
            notesList.appendChild(li);
        });
    }

    // 新增備忘事項
    noteForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const text = noteInput.value.trim();
        if (!text) return;

        try {
            await callApi('api/notes', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ text })
            });
            noteInput.value = '';
            clearError();
            fetchNotes();
        } catch (error) {
            showError('新增備忘事項失敗：' + error.message);
        }
    });

    // 刪除備忘事項
    async function deleteNote(id) {
        try {
            await callApi('api/notes/' + encodeURIComponent(id), { method: 'DELETE' });
            clearError();
            fetchNotes();
        } catch (error) {
            showError('刪除備忘事項失敗：' + error.message);
        }
    }

    // 初始化
    fetchNotes();
});

